INSERT INTO LIVRO_CAPITULOS (TEMA_ID, TEMA, TEXTO, PRATICAS_JSON, VIDEOS, GERADO_EM) VALUES ({{temaId}}, '{{tema}}', '{{texto}}', '{{praticas}}', {{videos}}, DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s')) ON DUPLICATE KEY UPDATE TEMA = VALUES(TEMA), TEXTO = VALUES(TEXTO), PRATICAS_JSON = VALUES(PRATICAS_JSON), VIDEOS = VALUES(VIDEOS), GERADO_EM = VALUES(GERADO_EM)